EXPLAIN PIPELINE SELECT toStartOfHour(fromUnixTimestamp64Milli(t)) AS hour, argMin(bp, t) AS open, max(bp) AS high, min(bp) AS low, argMax(bp, t) AS close, sum(bs) AS volume, sum(bp * bs) / sum(bs) AS vwap, stddevPop(bp) AS volatility, avg(ap - bp) AS avg_spread, count() AS ticks FROM quotes WHERE sym = 'AAPL' GROUP BY hour ORDER BY hour LIMIT 1000000 SETTINGS max_threads=30,enable_parallel_replicas=0,max_parallel_replicas=1,use_query_cache=0,log_queries=1,log_query_settings=1,log_queries_probability=1,log_queries_min_query_duration_ms=0,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=1000000000,max_bytes_to_read=100000000000,max_result_rows=1000000,result_overflow_mode='throw',log_comment='reader-scaling-pipeline-check' FORMAT TabSeparatedRaw
